import { tags } from "typia";

/**
 * Metrics describing how refund activity correlates with disputes and
 * chargebacks.
 *
 * These values are intended to give risk and governance teams insight into how
 * often refunds escalate into higher-severity dispute workflows or are related
 * to chargeback activity.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAnalyticsRefundDisputeCorrelation = {
  /**
   * Number of refunds that are associated with at least one dispute record in
   * the analysis window.
   */
  refundsWithDisputesCount?:
    | (number & tags.Type<"int32"> & tags.Minimum<0>)
    | undefined;

  /**
   * Proportion of refunds that escalated into disputes, expressed as a
   * fraction between 0 and 1.
   */
  refundsWithDisputesRate?: (number & tags.Minimum<0>) | undefined;

  /**
   * Number of refunds that are directly or indirectly associated with payment
   * chargeback cases in the analysis window.
   */
  refundsRelatedToChargebacksCount?:
    | (number & tags.Type<"int32"> & tags.Minimum<0>)
    | undefined;

  /**
   * Proportion of refunds that are related to chargeback cases, expressed as
   * a fraction between 0 and 1.
   */
  refundsRelatedToChargebacksRate?: (number & tags.Minimum<0>) | undefined;
};
